CREATE TABLE public.coach_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL DEFAULT 'New conversation', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), generation_id uuid, generation_started_at timestamptz, UNIQUE(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.coach_threads TO authenticated; GRANT ALL ON public.coach_threads TO service_role;
ALTER TABLE public.coach_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner threads" ON public.coach_threads FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.coach_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL, user_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('user','assistant')), parts jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(thread_id,user_id) REFERENCES public.coach_threads(id,user_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,DELETE ON public.coach_messages TO authenticated; GRANT ALL ON public.coach_messages TO service_role;
ALTER TABLE public.coach_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner messages read" ON public.coach_messages FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Owner messages insert" ON public.coach_messages FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "Owner messages delete" ON public.coach_messages FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE INDEX coach_messages_thread_created ON public.coach_messages(thread_id,created_at);
CREATE TABLE public.coach_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), coach_user_id uuid NOT NULL, coach_name text NOT NULL, kind text NOT NULL CHECK(kind IN ('call','video')), starts_at timestamptz NOT NULL, duration_min integer NOT NULL DEFAULT 30 CHECK(duration_min BETWEEN 10 AND 180), is_available boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.coach_slots TO authenticated; GRANT ALL ON public.coach_slots TO service_role;
ALTER TABLE public.coach_slots ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read coach slots" ON public.coach_slots FOR SELECT TO authenticated USING(true);
CREATE POLICY "Manage coach slots" ON public.coach_slots FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR (coach_user_id=auth.uid() AND public.has_role(auth.uid(),'coach'))) WITH CHECK(public.has_role(auth.uid(),'admin') OR (coach_user_id=auth.uid() AND public.has_role(auth.uid(),'coach')));
CREATE TABLE public.coach_bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, slot_id uuid REFERENCES public.coach_slots(id), kind text NOT NULL CHECK(kind IN ('call','video','callback')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','completed','cancelled')), contact text NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.coach_bookings TO authenticated; GRANT ALL ON public.coach_bookings TO service_role;
ALTER TABLE public.coach_bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own bookings" ON public.coach_bookings FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.coach_slots s WHERE s.id=slot_id AND s.coach_user_id=auth.uid() AND public.has_role(auth.uid(),'coach')));
CREATE POLICY "Insert own bookings" ON public.coach_bookings FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending');
CREATE POLICY "Cancel own bookings" ON public.coach_bookings FOR UPDATE TO authenticated USING(user_id=auth.uid() AND status IN ('pending','confirmed')) WITH CHECK(user_id=auth.uid() AND status='cancelled');
CREATE POLICY "Manage bookings" ON public.coach_bookings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.coach_slots s WHERE s.id=slot_id AND s.coach_user_id=auth.uid() AND public.has_role(auth.uid(),'coach'))) WITH CHECK(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.coach_slots s WHERE s.id=slot_id AND s.coach_user_id=auth.uid() AND public.has_role(auth.uid(),'coach')));
CREATE POLICY "Delete own bookings" ON public.coach_bookings FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE UNIQUE INDEX coach_slot_live_booking ON public.coach_bookings(slot_id) WHERE status IN ('pending','confirmed') AND slot_id IS NOT NULL;
CREATE FUNCTION public.validate_coach_booking() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NOT public.has_role(auth.uid(),'admin') AND NOT EXISTS(SELECT 1 FROM public.coach_slots s WHERE s.id=OLD.slot_id AND s.coach_user_id=auth.uid() AND public.has_role(auth.uid(),'coach')) THEN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.slot_id IS DISTINCT FROM OLD.slot_id OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.contact IS DISTINCT FROM OLD.contact OR NEW.notes IS DISTINCT FROM OLD.notes OR NEW.status <> 'cancelled' THEN RAISE EXCEPTION 'Only cancellation is allowed'; END IF; END IF; IF TG_OP='INSERT' THEN IF NEW.kind='callback' THEN IF NEW.slot_id IS NOT NULL THEN RAISE EXCEPTION 'Callback does not use a slot'; END IF; ELSE IF NEW.slot_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.coach_slots s WHERE s.id=NEW.slot_id AND s.kind=NEW.kind AND s.is_available AND s.starts_at>now()) THEN RAISE EXCEPTION 'Slot is unavailable'; END IF; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_coach_booking BEFORE INSERT OR UPDATE ON public.coach_bookings FOR EACH ROW EXECUTE FUNCTION public.validate_coach_booking();